mapper.select:
SELECT b.*, COALESCE(c.code, s.code) AS partner_code, COALESCE(c.name, s.name) AS partner_name, v.voucher_no
FROM fin_bill b
LEFT JOIN scm_customer c ON b.kind = 'AR' AND c.id = b.partner_id
LEFT JOIN scm_supplier s ON b.kind = 'AP' AND s.id = b.partner_id
LEFT JOIN fin_voucher v ON v.id = b.voucher_id
WHERE ((b.kind = #{q.kind} AND b.partner_id = #{q.partnerId})

    OR (b.kind = 'AP' AND s.customer_id IS NOT NULL AND s.customer_id = #{q.partnerId})
)
AND b.status = #{q.status}

    AND (b.bill_no LIKE CONCAT('%', #{q.keyword}, '%') OR b.source_no LIKE CONCAT('%', #{q.keyword}, '%'))

AND b.status <> 'SETTLED' AND b.due_date < #{today}
AND b.bill_date >= #{q.beginDate}
AND b.bill_date <= #{q.endDate}
ORDER BY b.id DESC

SELECT x.partner_id, COALESCE(c.code, s.code) AS partner_code, COALESCE(c.name, s.name) AS partner_name, x.balance, x.not_due, x.d30, x.d60, x.d90, x.over90 FROM ( SELECT b.partner_id, SUM(b.sgn * (b.amount - COALESCE(st.settled, 0))) AS balance, SUM(CASE WHEN b.due_date >= #{asOf} THEN b.sgn * (b.amount - COALESCE(st.settled, 0)) ELSE 0 END) AS not_due, SUM(CASE WHEN b.due_date < #{asOf} AND b.due_date >= #{d30} THEN b.sgn * (b.amount - COALESCE(st.settled, 0)) ELSE 0 END) AS d30, SUM(CASE WHEN b.due_date < #{d30} AND b.due_date >= #{d60} THEN b.sgn * (b.amount - COALESCE(st.settled, 0)) ELSE 0 END) AS d60, SUM(CASE WHEN b.due_date < #{d60} AND b.due_date >= #{d90} THEN b.sgn * (b.amount - COALESCE(st.settled, 0)) ELSE 0 END) AS d90, SUM(CASE WHEN b.due_date < #{d90} THEN b.sgn * (b.amount - COALESCE(st.settled, 0)) ELSE 0 END) AS over90 FROM ( SELECT b0.id, b0.partner_id, 1 AS sgn, b0.amount, b0.due_date FROM fin_bill b0 WHERE b0.kind = #{kind} AND b0.bill_date <= #{asOf}
UNION ALL SELECT b1.id, sp.customer_id, -1, b1.amount, b1.due_date FROM fin_bill b1 JOIN scm_supplier sp ON sp.id = b1.partner_id WHERE b1.kind = 'AP' AND sp.customer_id IS NOT NULL AND b1.bill_date <= #{asOf}
) b
LEFT JOIN (SELECT y.bill_id, SUM(y.settled) AS settled FROM ( SELECT si.bill_id, si.amount + si.discount AS settled FROM fin_settlement_item si JOIN fin_settlement s ON s.id = si.settlement_id WHERE s.settle_date <= #{asOf} AND s.status = 'APPROVED' UNION ALL SELECT ni.bill_id, ni.amount FROM fin_netting_item ni JOIN fin_netting n ON n.id = ni.netting_id WHERE n.netting_date <= #{asOf} ) y GROUP BY y.bill_id) st ON st.bill_id = b.id GROUP BY b.partner_id ) x LEFT JOIN scm_customer c ON #{kind} = 'AR' AND c.id = x.partner_id LEFT JOIN scm_supplier s ON #{kind} = 'AP' AND s.id = x.partner_id WHERE x.balance <> 0 ORDER BY x.balance DESC
